//! Context Awareness & Proactive Knowledge Pushing
//!
//! Monitors session activity, detects context changes, and proactively pushes
//! relevant knowledge to connected clients via SSE notifications.
//!
//! ## Architecture
//!
//! ```text
//! ┌─────────────────────────────────────────────────────────────────────┐
//! │                    Session Activity Stream                           │
//! │  (tool calls, queries, context switches, idle patterns)            │
//! └──────────────────────────┬────────────────────────────────────────┘
//!                            │
//!                            ▼
//! ┌─────────────────────────────────────────────────────────────────────┐
//! │                   Context Monitor (Background Task)                │
//! │  • Tracks active sessions and their states                          │
//! │  • Detects patterns (new topics, stuck sessions, context gaps)     │
//! │  • Maintains sliding window of recent activity                      │
//! └──────────────────────────┬────────────────────────────────────────┘
//!                            │
//!                            ▼
//! ┌─────────────────────────────────────────────────────────────────────┐
//! │                 Knowledge Trigger Engine                           │
//! │  • Evaluates context against trigger rules                            │
//! │  • Scores knowledge relevance                                         │
//! │  • Rate-limits pushes to avoid spam                                   │
//! └──────────────────────────┬────────────────────────────────────────┘
//!                            │
//!                            ▼
//! ┌─────────────────────────────────────────────────────────────────────┐
//! │                    RAG Retriever                                     │
//! │  • Semantic search based on context                                   │
//! │  • Hybrid: recent activity + predicted needs                        │
//! │  • Filters already-known information                                  │
//! └──────────────────────────┬────────────────────────────────────────┘
//!                            │
//!                            ▼
//! ┌─────────────────────────────────────────────────────────────────────┐
//! │                SSE Push Notifications (Proactive)                  │
//! │  notification: {                                                     │
//! │    type: "knowledge_push",                                           │
//! │    trigger: "new_topic_detected",                                    │
//! │    relevance_score: 0.92,                                            │
//! │    content: { ... },                                                 │
//! │    suggested_action: "review_architecture_docs"                     │
//! │  }                                                                   │
//! └─────────────────────────────────────────────────────────────────────┘
//! ```
//!
//! ## Trigger Types
//!
//! - `new_topic_detected` - User started working on a new domain/area
//! - `stuck_session` - Repeated similar queries or errors detected
//! - `context_gap` - Query seems incomplete or missing prerequisite knowledge
//! - `pattern_match` - Usage pattern suggests need for specific resource
//! - `session_milestone` - Nth query in session, suggest review/summary
//! - `idle_recovery` - User returned after idle, refresh context

use crate::memory_store::{CognitiveMemoryStore, EntryQuery};
use crate::rag_pipeline::{
    RagPipeline, RetrievalMode, RetrievalProfile, default_collection_from_env,
    with_retrieval_deadline,
};
use anyhow::{Context as AnyhowContext, Result};
use dashmap::DashMap;
use op_plugins::state_plugins::project::namespace_prefix_for_session;
use serde::{Deserialize, Serialize};
use std::collections::VecDeque;
use std::sync::Arc;
use std::time::Instant;
use tokio::sync::{RwLock, broadcast, mpsc};
use tracing::{info, trace, warn};

/// Maximum activity window to keep per session
const ACTIVITY_WINDOW_SIZE: usize = 50;
/// Minimum time between proactive pushes to same session
const MIN_PUSH_INTERVAL_SECS: u64 = 30;
/// Idle threshold for context refresh (seconds)
const IDLE_REFRESH_THRESHOLD_SECS: u64 = 300; // 5 minutes
/// Minimum relevance score to push knowledge
const MIN_RELEVANCE_SCORE: f32 = 0.75;

/// Types of knowledge push triggers
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PushTrigger {
    /// User started working on a new topic/domain
    NewTopicDetected,
    /// Session seems stuck (repeated similar queries/errors)
    StuckSession,
    /// Query appears incomplete or missing context
    ContextGap,
    /// Usage pattern suggests specific resource need
    PatternMatch,
    /// Session milestone reached (e.g., 10th query)
    SessionMilestone,
    /// User returned after idle period
    IdleRecovery,
    /// Tool usage suggests knowledge gap
    ToolGuidance,
    /// Error pattern detected
    ErrorAssistance,
}

/// Memory loop — owns CozoDB + Qdrant for chatbot memory
pub struct MemoryLoop {
    cozo: Arc<CognitiveMemoryStore>,
    qdrant: Option<Arc<QdrantSemanticShuttle>>,
    /// Regex for detecting memorable phrases in conversation
    memorable_regex: Regex,
}

impl MemoryLoop {
    pub fn new(cozo: Arc<CognitiveMemoryStore>) -> Self {
        Self {
            cozo,
            qdrant: None,
            memorable_regex: Regex::new(
                r"(?i)\b(always|never|prefer|my\s+(?:name|email|project)|our\s+project|decided\s+to|goal\s+is|important|remember\s+that|don't\s+forget)\b"
            ).expect("hardcoded regex pattern is valid"),
        }
    }

    pub fn with_qdrant(mut self, qdrant: Arc<QdrantSemanticShuttle>) -> Self {
        self.qdrant = Some(qdrant);
        self
    }

    /// Namespace name for a container's domain memory
    fn namespace_for(container_id: &str) -> String {
        format!("container:{}", container_id)
    }

    // ── Session Start Injection ──────────────────────────────────────────

    /// Load all four memory layers for a session start
    ///
    /// Hierarchy:
    /// 1. System-wide memory (global) — all authenticated entities
    /// 2. Chatbot soul — chatbot is a user entity, session-scoped
    /// 3. User container memory — assigned at registration, soul + domain namespace
    pub async fn inject_session_memory(
        &self,
        chatbot_soul_id: &str,   // e.g. "chatbot" or session-scoped id
        user_container_id: &str, // user's assigned container (work/home/...)
        opening_message: &str,
    ) -> Result<SessionMemory> {
        let user_ns = Self::namespace_for(user_container_id);

        // 1. System-wide memory — global namespace, all users/chatbots
        let system_block = self.load_system_memory().await.unwrap_or_default();

        // 2. Chatbot soul — chatbot is a user entity with its own soul
        let soul_block = self.load_soul(chatbot_soul_id).await.unwrap_or_default();

        // 3. User container domain memory — MEMORY_INDEX + full entries
        let (index_block, domain_block) = self
            .load_domain_memory(&user_ns, Some(opening_message))
            .await?;

        Ok(SessionMemory {
            system_block,
            soul_block,
            domain_block,
            index_block,
        })
    }

    /// Load system-wide global memory from CozoDB
    async fn load_system_memory(&self) -> Result<String> {
        let entry = self
            .cozo
            .retrieve_entry("system:global", "memory")
            .await
            .context("system memory lookup failed")?;

        Ok(entry.map(|e| format!("{}", e.value)).unwrap_or_default())
    }

    /// Load soul for a user entity (chatbot or container) from CognitiveMemoryStore
    async fn load_soul(&self, soul_id: &str) -> Result<String> {
        let entry = self
            .cozo
            .retrieve_entry("soul", soul_id)
            .await
            .context("soul lookup failed")?;

        Ok(entry.map(|e| format!("{}", e.value)).unwrap_or_default())
    }

    /// Load domain memory: MEMORY_INDEX orientation + full entries (+ optional semantic query)
    async fn load_domain_memory(
        &self,
        namespace: &str,
        query_text: Option<&str>,
    ) -> Result<(String, String)> {
        // MEMORY_INDEX key gives orientation
        let index = self
            .cozo
            .retrieve_entry(namespace, "MEMORY_INDEX")
            .await
            .context("MEMORY_INDEX lookup")?;

        let index_block = index
            .map(|e| e.value.as_str().map(|s| s.to_string()).unwrap_or_default())
            .unwrap_or_default();

        // Query full entries (excluding index itself)
        let entries = self
            .cozo
            .query_entries(EntryQuery {
