149:        .ok_or_else(|| ProjectionRefusal::UnknownSchema(schema.to_string()))?;
150:    if !table.purposes.contains(&purpose) {
151:        return Err(ProjectionRefusal::UnknownPurpose(format!(
152:            "{schema}:{}",
153:            match purpose {
154:                Purpose::Vectorize => "vectorize",
155:                Purpose::Display => "display",
156:                Purpose::Overlay => "overlay",
157:            }
158:        )));
159:    }
160:    let gate_open = value.pointer(table.pii_gate) != Some(&Value::Bool(true));
161:    let mut out = serde_json::Map::new();
162:    for rule in table.fields {
