164:            continue;
165:        }
166:        if let Some(v) = value.pointer(rule.path) {
167:            if !v.is_null() {
168:                out.insert(rule.path[1..].to_string(), v.clone());
169:            }
170:        }
171:    }
172:    Ok(Value::Object(out))
173:}
